import type { DHParameters, ForwardKinematicsResult, Mat4 } from '@/types/kinematics';
import type { AngleTriple, ArmGeometry } from '@/types/robot';
import { IDENTITY, axisOf, dhTransform, multiply, translationOf } from '@/utils/mat4';

/**
 * Real-time forward kinematics for the 3-DOF RRR arm.
 *
 * This is a line-by-line port of backend/app/robotics/kinematics.py (the
 * reference implementation). Equivalence is enforced by
 * forwardKinematics.test.ts against shared/fixtures/kinematics-reference.json,
 * which is generated by the backend.
 *
 * DH table (standard convention):
 *   link 1: θ=q1, d=L0, a=0,  α=+π/2
 *   link 2: θ=q2, d=0,  a=L1, α=0
 *   link 3: θ=q3, d=0,  a=L2, α=0
 */
export function dhTable(
  geometry: ArmGeometry,
  angles: AngleTriple,
): [DHParameters, DHParameters, DHParameters] {
  const [q1, q2, q3] = angles;
  return [
    { theta: q1, d: geometry.baseHeight, a: 0, alpha: Math.PI / 2 },
    { theta: q2, d: 0, a: geometry.upperArmLength, alpha: 0 },
    { theta: q3, d: 0, a: geometry.forearmLength, alpha: 0 },
  ];
}

export function forwardKinematics(
  geometry: ArmGeometry,
  angles: AngleTriple,
): ForwardKinematicsResult {
  if (!angles.every(Number.isFinite)) throw new RangeError('joint angles must be finite numbers');
  if (
    ![geometry.baseHeight, geometry.upperArmLength, geometry.forearmLength].every(Number.isFinite)
  ) {
    throw new RangeError('geometry values must be finite numbers');
  }

  const table = dhTable(geometry, angles);
  const local = table.map((p) => dhTransform(p.theta, p.d, p.a, p.alpha)) as [Mat4, Mat4, Mat4];

  const t01 = local[0];
  const t02 = multiply(t01, local[1]);
  const t03 = multiply(t02, local[2]);
  const frames: [Mat4, Mat4, Mat4] = [t01, t02, t03];

  // Joint i sits at the origin of frame {i-1} and rotates about z_{i-1}.
  const parents: [Mat4, Mat4, Mat4] = [IDENTITY, t01, t02];

  return {
    jointAngles: [...angles],
    dhTable: table,
    localTransforms: local,
    frames,
    joints: [
      { id: 'j1', position: translationOf(parents[0]), axis: axisOf(parents[0], 2) },
      { id: 'j2', position: translationOf(parents[1]), axis: axisOf(parents[1], 2) },
      { id: 'j3', position: translationOf(parents[2]), axis: axisOf(parents[2], 2) },
    ],
    endEffector: { position: translationOf(t03), transform: t03 },
  };
}
